};

/**
 * Drag-to-zoom selection shared by the line/area/bar charts. Wires chart-level
 * mouse handlers that track a horizontal drag across buckets, renders the
 * in-progress selection as a translucent <ReferenceArea />, and reports the
 * selected x range on release. A press that never leaves its starting bucket
 * stays a click — series click-to-select keeps working; after a real zoom,
 * `suppressClickRef` stays set for a tick so the release doesn't also toggle
 * the series selection under the pointer.
 */
export function useZoomDrag({
	data,
	xDataKey,
	onZoomSelect,
	disabled = false,
}: ZoomDragOptions) {
	const [selection, setSelection] = useState<{
		start: number;
		end: number;
	} | null>(null);
	// Mirror of `selection` for the mouseup handler: reading it from a ref keeps
	// the zoom callback *outside* any state updater — calling it from inside one
	// would update ancestor state (the date range) mid-render, which React
	// forbids ("Cannot update a component while rendering a different one").
	const selectionRef = useRef(selection);
	const suppressClickRef = useRef(false);
	const enabled = !!onZoomSelect && !!xDataKey && !disabled;

	const select = useCallback((sel: { start: number; end: number } | null) => {
		selectionRef.current = sel;
		setSelection(sel);
	}, []);

	const onMouseDown = useCallback(
		(state: unknown) => {
			if (!enabled) return;
			const idx = activeIndexOf(state);
			if (idx === null) return;
			select({ start: idx, end: idx });
		},
		[enabled, select],
	);

	const onMouseMove = useCallback(
		(state: unknown) => {
			const sel = selectionRef.current;
			if (!sel) return; // only tracks while a drag is in progress
			const idx = activeIndexOf(state);
			if (idx === null || idx === sel.end) return; // re-render per bucket, not per pixel
			select({ start: sel.start, end: idx });
		},
		[select],
	);

	const onMouseUp = useCallback(() => {
		const sel = selectionRef.current;
		select(null);
		if (!sel || !enabled || !xDataKey) return;
		const lo = Math.min(sel.start, sel.end);
		const hi = Math.max(sel.start, sel.end);
		// A press that stayed in one bucket is a click, not a zoom.
		if (hi - lo < 1) return;
		const startX = data[lo]?.[xDataKey];
		const endX = data[hi]?.[xDataKey];
		if (startX == null || endX == null) return;
		// The browser still fires a click on the element under the pointer
		// after this mouseup; hold the flag through it so the release of a
		// zoom drag can't also toggle a series selection.
		suppressClickRef.current = true;
		setTimeout(() => {
			suppressClickRef.current = false;
		}, 0);
		onZoomSelect?.(String(startX), String(endX));
	}, [data, xDataKey, onZoomSelect, enabled, select]);

	const onMouseLeave = useCallback(() => {
		select(null);
	}, [select]);

	let overlay: React.ReactNode = null;
	if (selection && enabled && xDataKey) {
		const lo = Math.min(selection.start, selection.end);
		const hi = Math.max(selection.start, selection.end);
		const x1 = data[lo]?.[xDataKey];
		const x2 = data[hi]?.[xDataKey];
		if (x1 != null && x2 != null) {
			// A ReferenceArea strokes all four edges of its rect; drawing the
			// fill without a stroke and marking the edges with ReferenceLines
			// keeps only the vertical sides dashed.
			overlay = (
				<>
					<ReferenceArea
						x1={String(x1)}
						x2={String(x2)}
						fill="var(--foreground)"
						fillOpacity={0.06}
						stroke="none"
					/>
					<ReferenceLine
						x={String(x1)}
						stroke="var(--foreground)"
						strokeOpacity={0.25}
						strokeDasharray="2 2"
					/>
					<ReferenceLine
						x={String(x2)}
						stroke="var(--foreground)"
						strokeOpacity={0.25}
						strokeDasharray="2 2"
					/>
				</>
			);
		}
	}

	return {
		enabled,
		overlay,
		suppressClickRef,
		handlers: { onMouseDown, onMouseMove, onMouseUp, onMouseLeave },
	};
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/format.ts; derived here under Apache-2.0.
 */
const usdFormatters = new Map<string, Intl.NumberFormat>();
function usdFormatter(minDecimals: number, maxDecimals: number) {
	const key = `${minDecimals}:${maxDecimals}`;
	let f = usdFormatters.get(key);
	if (!f) {
		f = new Intl.NumberFormat("en-US", {
			style: "currency",
			currency: "USD",
			minimumFractionDigits: minDecimals,
			maximumFractionDigits: maxDecimals,
		});
		usdFormatters.set(key, f);
	}
	return f;
}

/** A cost value; `null`/`undefined` → em dash (unpriced, never $0). `maxDecimals`
 * caps the fractional digits — 6 (full precision) by default, 4 for the more
 * compact stat-card treatment. Trailing zeros are trimmed back to 2 decimals. */
export function formatCost(
	value: number | null | undefined,
	maxDecimals = 6,
): string {
	if (value === null || value === undefined) return "—";
	return usdFormatter(2, maxDecimals).format(value);
}

/** A cost value padded to exactly `decimals` fraction digits, so a column of
 * them lines up on the decimal point ("$0.003350" above "$0.002773") instead of
 * raggedly trimming trailing zeros. For table cells; elsewhere use `formatCost`,
 * which keeps numbers short. */
export function formatCostFixed(
	value: number | null | undefined,
	decimals: number,
): string {
	if (value === null || value === undefined) return "—";
	return usdFormatter(decimals, decimals).format(value);
}

const compact = new Intl.NumberFormat("en-US", { notation: "compact" });
const plain = new Intl.NumberFormat("en-US");

// Count formatters round first: counts are integers by definition, but animated
// stat tickers feed them fractional in-between frames, which would otherwise
// render decimals mid-tween ("1,234.567").
export function formatCount(value: number): string {
	const n = Math.round(value);
	return n >= 1000 ? compact.format(n) : plain.format(n);
}

/** A count with no compaction — "1,024", never "1K". For operator figures where
 * the exact number is the point and 1,024 vs 1,499 must not both read "1K". */
export function formatExactCount(value: number): string {
	return plain.format(Math.round(value));
}

export function formatTokens(value: number): string {
	return compact.format(value);
}

/** Milliseconds → human duration (µs/ms/s/m/h/d). */
export function formatDuration(ms: number): string {
	if (!Number.isFinite(ms)) return "—";
	// Exact zero reads as "0s" (not "0µs") everywhere — e.g. latency axes anchored
	// at the origin.
	if (ms === 0) return "0s";
	if (ms < 1) return `${Math.round(ms * 1000)}µs`;
	if (ms < 1000) return `${Math.round(ms)}ms`;
	if (ms < 60_000) return `${(ms / 1000).toFixed(2)}s`;
	// Beyond a minute, build from the largest non-zero unit and show at most two
	// components so e.g. an even hour reads "1h", not "60m 0s".
	const totalSec = Math.round(ms / 1000);
	const d = Math.floor(totalSec / 86_400);
	const h = Math.floor((totalSec % 86_400) / 3600);
	const m = Math.floor((totalSec % 3600) / 60);
	const s = totalSec % 60;
	const parts = [];
	if (d) parts.push(`${d}d`);
	if (h) parts.push(`${h}h`);
	if (m) parts.push(`${m}m`);
	if (s) parts.push(`${s}s`);
	return parts.slice(0, 2).join(" ") || "0s";
}

/** A recorded span/trace duration. Storage is whole milliseconds, so an exact 0
 * means "finished in under 1ms", not "took no time" — render it as such. Axes
 * and aggregates should keep using formatDuration ("0s" at the origin). */
export function formatSpanDuration(ms: number): string {
	if (ms === 0) return "<1ms";
	return formatDuration(ms);
}

export function formatPercent(fraction: number | null | undefined): string {
	if (fraction === null || fraction === undefined) return "—";
	return `${Math.round(fraction * 100)}%`;
}

/** ClickHouse DateTime strings ('YYYY-MM-DD HH:MM:SS', UTC) or ISO → Date. */
export function parseDateTime(value: string | Date): Date {
	if (value instanceof Date) return value;

	const normalized = value.replace(" ", "T");
	const hasTimezone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(normalized);
	return new Date(hasTimezone ? normalized : `${normalized}Z`);
}

/** ClickHouse DateTime strings ('YYYY-MM-DD HH:MM:SS', UTC) or ISO → local. */
export function formatDateTime(
	value: string | Date | null | undefined,
): string {
	if (!value) return "—";
	const d = parseDateTime(value);
	if (Number.isNaN(d.getTime())) return String(value);
	return d.toLocaleString(undefined, {
		month: "short",
		day: "numeric",
		hour: "2-digit",
		minute: "2-digit",
		second: "2-digit",
		// Always 24-hour, regardless of the viewer's locale default.
		hour12: false,
	});
}

export function formatRelative(
	value: string | Date | null | undefined,
): string {
	if (!value) return "—";
	const d = parseDateTime(value);
	const diff = Date.now() - d.getTime();
	if (Number.isNaN(diff)) return String(value);
	// Clamp clock skew: a server timestamp slightly ahead of the client must not
	// render as "-3s ago".
	const sec = Math.max(0, Math.round(diff / 1000));
	if (sec < 60) return `${sec}s ago`;
	const min = Math.round(sec / 60);
	if (min < 60) return `${min}m ago`;
	const hr = Math.round(min / 60);
	if (hr < 24) return `${hr}h ago`;
	return `${Math.round(hr / 24)}d ago`;
}

export type Delta = { pct: number; dir: "up" | "down" | "flat" };

/**
 * Period-over-period change as a fraction + direction. `null` when there's no
 * baseline to compare against (previous is null/zero) — the caller renders "—".
 */
export function formatDelta(
	current: number | null | undefined,
	previous: number | null | undefined,
): Delta | null {
	if (current === null || current === undefined) return null;
	if (previous === null || previous === undefined || previous === 0)
		return null;
	const pct = (current - previous) / previous;
	const dir = Math.abs(pct) < 0.0001 ? "flat" : pct > 0 ? "up" : "down";
	return { pct, dir };
}

/** Extrapolate a window's cost to a 30-day run-rate. `null` when cost is unknown. */
export function projectMonthlyCost(
	cost: number | null | undefined,
	windowMs: number,
): number | null {
	if (cost === null || cost === undefined || windowMs <= 0) return null;
	const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;
	return (cost / windowMs) * THIRTY_DAYS;
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/range.ts; derived here under Apache-2.0.
 */
import {
  endOfDay,
  endOfMonth,
  format,
  startOfDay,
  startOfMonth,
  subDays,
  subHours,
  subMonths,
} from "date-fns";

export type RangeValue = {
  /** Originating preset key, or "custom" for a calendar-selected range. */
  key: string;
  label: string;
  from: Date;
  to: Date;
};

type Preset = {
  key: string;
  label: string;
  resolve: (now: Date) => { from: Date; to: Date };
};

export const RANGE_PRESETS: Preset[] = [
  {
    key: "1h",
    label: "Last hour",
    resolve: (n) => ({ from: subHours(n, 1), to: n }),
  },
  {
    key: "24h",
    label: "Last 24 hours",
    resolve: (n) => ({ from: subHours(n, 24), to: n }),
  },
  {
    key: "3d",
    label: "Last 3 days",
    resolve: (n) => ({ from: subDays(n, 3), to: n }),
  },
  {
    key: "7d",
    label: "Last 7 days",
    resolve: (n) => ({ from: subDays(n, 7), to: n }),
  },
  {
    key: "30d",
    label: "Last 30 days",
    resolve: (n) => ({ from: subDays(n, 30), to: n }),
  },
  {
    key: "90d",
    label: "Last 90 days",
    resolve: (n) => ({ from: subDays(n, 90), to: n }),
  },
  {
    key: "today",
    label: "Today",
    resolve: (n) => ({ from: startOfDay(n), to: n }),
  },
  {
    key: "month",
    label: "This month",
    resolve: (n) => ({ from: startOfMonth(n), to: n }),
  },
  {
    key: "lastMonth",
    label: "Last month",
    resolve: (n) => {
      const start = startOfMonth(subMonths(n, 1));
      return { from: start, to: endOfMonth(start) };
    },
  },
];

export function resolvePreset(key: string, now: Date = new Date()): RangeValue {
  const p = RANGE_PRESETS.find((x) => x.key === key) ?? RANGE_PRESETS[1]!;
  const { from, to } = p.resolve(now);
  return { key: p.key, label: p.label, from, to };
}

export function defaultRange(): RangeValue {
  return resolvePreset("24h");
}

/** A calendar-selected absolute range (whole days, inclusive of the end day). */
export function customRange(from: Date, to: Date): RangeValue {
  const f = startOfDay(from);
  const t = endOfDay(to);
  return { key: "custom", label: formatRangeLabel(f, t), from: f, to: t };
}

/** An absolute range at full time precision — produced by dragging a zoom
 * selection on a chart (and used to restore stored custom ranges verbatim).
 * Whole-day ranges keep the calendar picker's date-only label. */
export function exactRange(from: Date, to: Date): RangeValue {
  return { key: "custom", label: formatExactLabel(from, to), from, to };
}

function formatExactLabel(from: Date, to: Date): string {
  const wholeDays =
    from.getTime() === startOfDay(from).getTime() &&
    to.getTime() === endOfDay(to).getTime();
  if (wholeDays) return formatRangeLabel(from, to);
  const sameDay = startOfDay(from).getTime() === startOfDay(to).getTime();
  if (sameDay) return `${format(from, "MMM d, HH:mm")} – ${format(to, "HH:mm")}`;
  const sameYear = from.getFullYear() === to.getFullYear();
  const fmt = sameYear ? "MMM d, HH:mm" : "MMM d, yyyy HH:mm";
  return `${format(from, fmt)} – ${format(to, fmt)}`;
}

/** Absolute readout of a resolved window, minute precision — "Aug 10, 14:32 –
 * Aug 11, 14:32". The year only appears when it isn't the current one. */
export function formatRangeWindow(
  from: Date,
  to: Date,
  now: Date = new Date()
): string {
  const fmt = (d: Date) =>
    format(
      d,
      d.getFullYear() === now.getFullYear()
        ? "MMM d, HH:mm"
        : "MMM d, yyyy, HH:mm"
    );
  return `${fmt(from)} to ${fmt(to)}`;
}

export function formatRangeLabel(from: Date, to: Date): string {
  const sameDay = startOfDay(from).getTime() === startOfDay(to).getTime();
  if (sameDay) return format(from, "MMM d, yyyy");
  const sameYear = from.getFullYear() === to.getFullYear();
  return `${format(from, sameYear ? "MMM d" : "MMM d, yyyy")} – ${format(
    to,
    "MMM d, yyyy"
  )}`;
}

